{
  "arguments": [
    {
      "claim": "The commander exercised effective command and control over the Military Police after 27 November 1992, satisfying the control element of command responsibility.",
      "reasoning": "The Trial Chamber’s findings that the Military Police was subordinated to the commander through successive Chiefs of Staff after that date establish that the commander had the requisite effective authority and control over the forces that committed the crimes. Article 28 of the Rome Statute mirrors the ICTY standard, requiring that a commander have \"effective command and control, or effective authority and control\" over the forces whose conduct gives rise to liability.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "A military commander or person effectively acting as a military commander shall be criminally responsible for crimes within the jurisdiction of the Court committed by forces under his or her effective command and control, or effective authority and control as the case may be, as a result of his or her failure to exercise control properly over such forces"
        }
      ]
    },
    {
      "claim": "The commander knew, or had reason to know, that murder and cruel treatment were being committed against Serb detainees.",
      "reasoning": "Customary international humanitarian law imposes liability when a superior \"knew, or had reason to know\" of the commission of crimes by subordinates. The factual record shows the commander was aware of the existence of the two detention facilities, the timing of the crimes, and that the Military Police operated under his authority, giving him the requisite knowledge or constructive knowledge.",
      "citations": [
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates if they knew, or had reason to know, that the subordinates were about to commit or were committing such crimes"
        }
      ]
    },
    {
      "claim": "The commander failed to take all necessary and reasonable measures within his power to prevent or repress the murders and cruel treatment between 27 December 1992 and 20 March 1993.",
      "reasoning": "Both the Rome Statute (art.28) and Additional Protocol I (art.86(2)) require that a superior who knows or should know of crimes must take \"all necessary and reasonable measures\" to prevent or repress them. The commander neither issued orders to halt the abuses nor instituted any effective oversight or disciplinary action, thereby breaching this duty.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "That military commander or person failed to take all necessary and reasonable measures within his or her power to prevent or repress their commission or to submit the matter to the competent authorities for investigation and prosecution"
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)",
          "quoted_text": "if they did not take all feasible measures within their power to prevent or repress the breach"
        }
      ]
    },
    {
      "claim": "The fact that the actual perpetrators were not members of the Military Police does not absolve the commander of responsibility because command responsibility extends to crimes committed by forces under his effective control, and he could have prevented or punished the perpetrators.",
      "reasoning": "Customary rule 153 expressly includes liability for failure to punish persons responsible for crimes, irrespective of their formal affiliation, once the superior has effective authority. The commander’s effective control over the Military Police, which was the unit exercising authority over the detention sites, means he could have intervened to stop the crimes or to hold the perpetrators accountable.",
      "citations": [
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "or if such crimes had been committed, to punish the persons responsible"
        },
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "as a result of his or her failure to exercise control properly over such forces"
        }
      ]
    },
    {
      "claim": "All elements of command responsibility under Article 7(3) of the ICTY Statute have been proven beyond reasonable doubt, making the conviction consistent with established international law.",
      "reasoning": "The three cumulative elements—effective control, knowledge (or constructive knowledge), and failure to take all necessary and reasonable measures—are each satisfied by the factual findings and are reflected in the parallel provisions of the Rome Statute, Additional Protocol I, and customary IHL. The convergence of these sources demonstrates that the evidentiary threshold of beyond‑reasonable‑doubt has been met, justifying the conviction.",
      "citations": [
        {
          "type": "treaty",
          "instrument": "rome_statute",
          "article": "28",
          "quoted_text": "A military commander or person effectively acting as a military commander shall be criminally responsible for crimes within the jurisdiction of the Court committed by forces under his or her effective command and control"
        },
        {
          "type": "customary",
          "instrument": "customary_ihl",
          "rule_number": 153,
          "quoted_text": "Commanders and other superiors are criminally responsible for war crimes committed by their subordinates if they knew, or had reason to know, that the subordinates were about to commit or were committing such crimes and did not take all necessary and reasonable measures in their power to prevent their commission"
        },
        {
          "type": "treaty",
          "instrument": "ap_i",
          "article": "86(2)",
          "quoted_text": "if they did not take all feasible measures within their power to prevent or repress the breach"
        }
      ]
    }
  ]
}

